import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

// File path for the continuous live stream state generated by stream_service.py
const STATE_FILE = path.join(process.cwd(), 'live_stream_state.json');

export async function GET() {
  try {
    if (fs.existsSync(STATE_FILE)) {
      const raw = fs.readFileSync(STATE_FILE, 'utf-8');
      const data = JSON.parse(raw);
      return NextResponse.json({
        status: 'streaming',
        source: 'kumaracharm/data (BIDMC + Synthea)',
        timestamp: data.timestamp || new Date().toISOString(),
        patientCount: data.patient_count || 10,
        patients: data.patients || {},
      }, {
        headers: {
          'Cache-Control': 'no-store, max-age=0',
          'Access-Control-Allow-Origin': '*',
        }
      });
    }

    // Fallback if feeder is initializing
    return NextResponse.json({
      status: 'initializing',
      source: 'kumaracharm/data (BIDMC + Synthea)',
      timestamp: new Date().toISOString(),
      patientCount: 0,
      patients: {},
    });
  } catch (err: any) {
    return NextResponse.json({
      status: 'error',
      message: err.message,
    }, { status: 500 });
  }
}

